#include "stdlib/blas/ext/base/dcartesiansquare.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"

/**
* Computes the Cartesian square for a double-precision floating-point strided array.
*
* @param N           number of indexed elements
* @param X           input array
* @param strideX     stride length
* @param Out         output array
* @param strideOut1  stride length between consecutive output pairs
* @param strideOut2  stride length between elements of each output pair
*/
void API_SUFFIX(stdlib_strided_dcartesian_square)( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, double *Out, const CBLAS_INT strideOut1, const CBLAS_INT strideOut2 ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	CBLAS_INT oo = stdlib_strided_stride2offset( N*N, strideOut1 ) + stdlib_strided_stride2offset( 2, strideOut2 );
	API_SUFFIX(stdlib_strided_dcartesian_square_ndarray)( N, X, strideX, ox, Out, strideOut1, strideOut2, oo );
}

/**
* Computes the Cartesian square for a double-precision floating-point strided array using alternative indexing semantics.
*
* @param N           number of indexed elements
* @param X           input array
* @param strideX     stride length
* @param offsetX     starting index
* @param Out         output array
* @param strideOut1  stride length between consecutive output pairs
* @param strideOut2  stride length between elements of each output pair
* @param offsetOut   starting index
*/
void API_SUFFIX(stdlib_strided_dcartesian_square_ndarray)( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, double *Out, const CBLAS_INT strideOut1, const CBLAS_INT strideOut2, const CBLAS_INT offsetOut ) {
	CBLAS_INT xi;
	CBLAS_INT xj;
	CBLAS_INT io;
	CBLAS_INT i;
	CBLAS_INT j;
	double v;

	if ( N <= 0 ) {
		return;
	}
	xi = offsetX;
	io = offsetOut;
	for ( i = 0; i < N; i++ ) {
		v = X[ xi ];
		xj = offsetX;
		for ( j = 0; j < N; j++ ) {
			Out[ io ] = v;
			Out[ io + strideOut2 ] = X[ xj ];
			io += strideOut1;
			xj += strideX;
		}
		xi += strideX;
	}
}
